/* ============ H: CHATS, UPDATES; N: NOTIFICATIONS ============ */
const chatAuthor=()=>cur()?.p.actor||'me';
const chatStore=(actor=chatAuthor())=>social(actor);
const lastMsg=(id,actor=chatAuthor())=>{const t=chatStore(actor)?.threads[id];return t?.msgs.at(-1);};
function threadIds(arch,actor=chatAuthor()){const st=chatStore(actor);if(!st||!authorAllowed(actor))return [];return Object.keys(st.threads).filter(k=>!isBlocked(k)&&(arch?st.archived.has(k):!st.archived.has(k))).sort((a,b)=>(lastMsg(b,actor)?.t||0)-(lastMsg(a,actor)?.t||0));}
function chatUnread(t){const reader=pairMember(),seen=t.readBy?.[reader];return seen==null?(t.unread||0):t.msgs.filter(m=>!m.me&&m.t>seen).length;}
function chatRow(id,actor='me'){const t=ensureThread(id,actor),m=lastMsg(id,actor),n=chatUnread(t);return `<button class="chat-row ${n?'unread':''}" data-go="H02" data-p='${JSON.stringify({id,actor})}'>${av(id,'round lg')}<span class="tx"><b>${esc(pname(id))}</b><small>${actor==='couple'?L('Мы · ','Us · '):L('Я · ','Me · ')}${m?esc(T(m.text)):L('Напиши первым','Say hi first')}</small></span><span class="side2">${n?`<span class="unr">${n}</span>`:''}<time>${m?F.short(m.t):''}</time></span></button>`;}
SC.H01={root:1,tab:'chats',title:()=>L('Чаты','Chats'),render:p=>{const f=p.kind||'all',q=(p.q||'').toLowerCase(),owners=(activePair()?['me','couple']:['me']).filter(a=>f==='all'||f===a);const rows=owners.flatMap(actor=>threadIds(false,actor).filter(id=>!q||pname(id).toLowerCase().includes(q)).map(id=>({id,actor,t:lastMsg(id,actor)?.t||0}))).sort((a,b)=>b.t-a.t);const fresh=owners.flatMap(actor=>social(actor).matches.filter(m=>!social(actor).threads[m.p]?.msgs.length&&!isBlocked(m.p)).map(m=>({...m,actor})));
 return `${bar(L('Чаты','Chats'),{actions:`<button class="ibtn" data-act="chatSearch" aria-label="${L('Поиск по чатам','Search chats')}">${I.search}</button>${bellBtn()}`})}<div class="view"><div class="wrap">${seg([['all',L('Все','All')],['me',L('Личные','Personal')],['couple',L('Пары','Couples')]],f,'chatKind')}${p.searching?`<input class="inp mt12" id="chatQ" aria-label="${L('Поиск по чатам','Search chats')}" value="${esc(p.q||'')}" data-in="chatQ">`:''}${fresh.length?`<div class="sec">${L('Новые совпадения','New matches')}</div><div class="matches">${fresh.map(m=>`<button data-act="openChat" data-v="${m.p}" data-actor="${m.actor}">${av(m.p,'round')}<span class="mn">${esc(pname(m.p))} · ${m.actor==='couple'?L('Мы','Us'):L('Я','Me')}</span></button>`).join('')}</div>`:''}${rows.map(x=>chatRow(x.id,x.actor)).join('')||empty('chat',L('Пока нет диалогов','No conversations yet'),L('Чат открывается после взаимной симпатии.','A mutual like opens a chat.'))}<button class="btn text" data-go="H05">${L('Архив','Archive')}</button></div></div>`;}};
ACT.chatKind=a=>setP('kind',a.dataset.v);
ACT.hSub=a=>setSub(a.dataset.v);
ACT.toPeople=()=>tab('people',{sub:'discover'});
ACT.chatSearch=()=>{const r=cur();r.p.searching=!r.p.searching;r.p.q='';refresh();$('#chatQ')?.focus();};
IN.chatQ=el=>{cur().p.q=el.value;const pos=el.selectionStart;refresh();const n=$('#chatQ');n.focus();n.setSelectionRange(pos,pos);};
ACT.openUpdate=a=>{const u=S.updates.find(x=>x.id===a.dataset.v);if(!u)return;u.read=true;if(u.e)go('E03',{id:u.e});else go('C03',{id:u.c});};

/* H02 — conversation */
SC.H02={title:p=>pname(p.id),valid:p=>authorAllowed(p.actor||'me')&&!!PEOPLE[p.id]&&(isMatch(p.id,p.actor||'me')||!!social(p.actor||'me')?.threads[p.id]?.ended)&&!isBlocked(p.id),render:(p,r)=>{const id=p.id;const t=ensureThread(id,p.actor||'me');
 t.readBy[pairMember()]=Date.now();if(!t.pair)t.unread=0;
 const ended=t.ended||!isMatch(id);
 const sh=shared(id);const g=receivedGrant(id);const mine=givenGrant(id);const m=chatStore().matches.find(x=>x.p===id);
 const pills=[`<button class="pill hot" data-go="P05" data-p='${JSON.stringify({id,actor:chatAuthor()})}'>${ic('spark',13)}${esc(sharedSummary(id))}</button>`,g?`<button class="pill ok" data-go="P08" data-p='${JSON.stringify({id,actor:chatAuthor()})}'>${I.unlock}${L('Тебе открыт профиль','Profile shared with you')}</button>`:`<button class="pill" data-act="reqAccess" data-v="${id}">${I.lock}${L('Расширенный профиль закрыт','Private profile closed')}</button>`,mine?`<span class="pill v">${I.eye}${L('Ты открыл(а) доступ','You shared access')}</span>`:''].join('');
 let lastDay='';const msgs=t.msgs.map((x,i)=>{const day=F.date(x.t);const sep=day!==lastDay?(lastDay=day,`<div class="daysep">${Date.now()-x.t<DAY&&new Date(x.t).getDate()===new Date().getDate()?L('Сегодня','Today'):day}</div>`):'';
  return sep+`<div class="msg ${x.me?'me':''} ${x.status||''} ${x.media?'has-media':''}">${t.pair?`<small class="note">${esc(pname(x.me?t.actor:id))} · ${esc(pname(x.sender||(x.me?'me':realMembers(id)[0])))}</small>`:''}${x.media?chatMediaHTML(x,i):''}${T(x.text)?`<span class="mtx">${esc(T(x.text))}</span>`:''}${x.me?`<div class="st">${F.time(x.t)}${x.status==='sending'?I.clock:x.status==='failed'?I.alert:I.check}</div>`:''}</div>${x.status==='failed'&&!ended?`<button class="msg-retry" data-act="retryMsg" data-v="${i}">${I.undo}${L('Не отправлено · Повторить','Not sent · Retry')}</button>`:''}`;}).join('');
 const ice=!ended&&!t.msgs.length?`<div class="sec">${L('С чего начать','Conversation starters')}</div><div class="chips">${(sh.match.length?sh.match.slice(0,2).map(tp=>L(`Как ты пришёл(ла) к теме «${topic(tp)}»?`,`How did you get into ${topic(tp)}?`)):[]).concat([L('Что тебе сейчас интересно изучить?','What would you like to explore right now?'),L('Как тебе удобнее общаться?','How do you prefer to keep in touch?')]).map(x=>`<button class="chip wrap" data-act="ice">${esc(x)}</button>`).join('')}</div>`:'';
 return `<header class="bar solid"><button class="ibtn ghost" data-back aria-label="${L('Назад','Back')}">${I.back}</button><button class="row grow" style="gap:10px;text-align:left;min-width:0" data-go="P01" data-p='${JSON.stringify({id,actor:chatAuthor()})}'>${av(id,'sm round '+(person(id).online?'on':''))}<span style="display:grid;min-width:0"><b style="font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(pname(id))}</b><small style="font-size:12px;color:${person(id).online?'var(--mint)':'var(--mute)'}">${t.pair?L('общий диалог пары','shared couple chat'):esc(presence(id))}</small></span></button><button class="ibtn ghost" data-act="chatMenu" data-v="${id}" aria-label="${L('Информация о диалоге','Conversation details')}">${I.more}</button></header>
 <div class="view nodock ${ended?'':'cta1'}"><div class="wrap"><div class="chat-ctx">${pills}</div><p class="note">${L('Пишешь от','Writing as')} <b>${esc(pname(chatAuthor()))}</b> · ${pl(t.members.length,['участник','участника','участников'],['participant','participants'])}</p><div class="chips">${t.members.map(m=>`<span class="chip">${esc(pname(m))}</span>`).join('')}</div>
 <div class="msgs" id="msgs"><div class="msg sys">${m?L(`Взаимная симпатия ${F.rel(m.t)}. Это один общий диалог.`,`Mutual like ${F.rel(m.t)}. This is one shared conversation.`):''}</div>${msgs}${!ended&&S.ui.typing===id?`<div class="typing"><i></i><i></i><i></i></div>`:''}</div>${ice}
 ${ended?`<div class="alert mt16">${I.block}<span><b>${L('Контакт прекращён','Connection ended')}</b>${L('Новые сообщения недоступны. История осталась у тебя.','No new messages. The history stays with you.')}</span></div>`:''}
 </div></div>${ended?'':`<div class="inputbar"><button class="ibtn ghost" data-act="attach" aria-label="${L('Вложение','Attach')}">${I.plus}</button><textarea id="msgIn" rows="1" placeholder="${L('Сообщение','Message')}" aria-label="${L('Сообщение','Message')}" title="${L('Enter — отправить, Shift+Enter — новая строка. На телефоне Enter — новая строка.','Enter sends, Shift+Enter adds a line. On phones Enter adds a line.')}" data-in="grow" data-enter="send" enterkeyhint="enter">${esc(r.f.msgIn||'')}</textarea><button class="ibtn send" data-act="send" aria-label="${L('Отправить','Send')}" ${(r.f.msgIn||'').trim()?'':'disabled'}>${I.send}</button></div>`}`;},
 after:(p)=>{const v=$('#main .view');if(v)v.scrollTop=v.scrollHeight;renderSide();chatTick();}};
ACT.ice=a=>{const el=$('#msgIn');if(!el||!isMatch(cur().p.id)||isBlocked(cur().p.id)||chatStore().threads[cur().p.id]?.ended)return;el.value=a.textContent;IN.grow(el);el.focus();};
ACT.send=()=>{const el=$('#msgIn');if(!el)return;const v=el.value.trim();if(!v)return;if(v.length>2000){toast(L('Слишком длинное сообщение: максимум 2000 символов','Message too long: 2000 characters max'),{type:'err'});return;}
 const id=cur().p.id;const t=chatStore().threads[id];if(!isMatch(id)||isBlocked(id)||t.ended)return;const owner=S,session=S.session,actor=chatAuthor(),store=chatStore();const live=()=>authorAllowed(actor)&&S===owner&&S.session===session&&!isBlocked(id)&&isMatch(id,actor)&&store.threads[id]===t&&!t.ended;const msg={me:1,author:chatAuthor(),sender:pairMember(),text:{ru:v,en:v},t:Date.now(),status:'sending'};t.msgs.push(msg);cur().f.msgIn='';refresh();
 net(400).then(()=>{if(!live())return;msg.status='';socialDelivery(id,'message',String(msg.t),{from:actor});if(cur().id==='H02')refresh();maybePush();
  if(!t.replied&&!t.pair){t.replied=1;setTimeout(()=>{if(!live())return;S.ui.typing=id;if(cur().id==='H02'&&cur().p.id===id)refresh();setTimeout(()=>{if(!live())return;S.ui.typing=null;store.archived.delete(id);t.msgs.push({me:0,text:{ru:'Интересный вопрос! Дай подумать пару минут 🙂',en:'Good question! Give me a couple of minutes 🙂'},t:Date.now()});if(cur().id==='H02'&&cur().p.id===id)refresh();else{t.unread=(t.unread||0)+1;renderSide();toast(L(`${pname(id)}: новое сообщение`,`${pname(id)}: new message`),{action:{label:L('Открыть','Open'),fn:()=>openChat(id)}});}},1800);},900);}
 }).catch(()=>{if(!live())return;msg.status='failed';if(cur().id==='H02')refresh();toast(L('Сообщение не отправлено. Текст сохранён','Message not sent. Your text is kept'),{type:'err'});});};
ACT.retryMsg=a=>{const id=cur().p.id;if(!isMatch(id)||isBlocked(id)||chatStore().threads[id]?.ended)return;const owner=S,actor=chatAuthor(),store=chatStore();const t=store.threads[id];const msg=t.msgs[+a.dataset.v];msg.status='sending';refresh();net(400).then(()=>{if(S!==owner||!authorAllowed(actor)||!isMatch(id,actor)||isBlocked(id)||t.ended)return;msg.status='';if(cur().id==='H02'&&cur().p.id===id)refresh();}).catch(()=>{if(S!==owner||isBlocked(id)||t.ended)return;msg.status='failed';refresh();toast(NETFAIL(),{type:'err'});});};
ACT.attach=()=>sheet(()=>({title:L('Отправить фото или видео','Send a photo or video'),body:`<div class="card list">${linkRow({act:'attPick',v:'gallery',icon:'image',tone:'v',title:L('Из галереи','From gallery'),sub:L('Фото или видео, до 1 файла','A photo or video, one file'),noChev:1})}${linkRow({act:'attPick',v:'cam',icon:'camera',title:L('Камера','Camera'),noChev:1})}</div><p class="note mt12">${L('Дальше выберешь, как его можно смотреть: обычное, один просмотр или исчезнет через время после просмотра.','Next you choose how it can be viewed: regular, view once, or gone some time after viewing.')}</p>`}));
ACT.attPick=async a=>{closeSheet(true);const id=cur().p.id,route=cur(),owner=S;if(!isMatch(id)||isBlocked(id)||chatStore().threads[id]?.ended)return;
 const files=await pickLocalMedia(a.dataset.v==='cam'?'image/*':'image/*,video/*',false);if(S!==owner||cur()!==route||!files.length)return;S.ui.cm={id,file:files[0],mode:'normal'};sheet(chatSendSheet,{guard:()=>!!S.ui.cm});};
/* ---------- V10 revision part 7: chat media — blur, view once, timed after first view ---------- */
const CM_TTL={t15:15*60e3,t120:2*3600e3,t1440:24*3600e3};
const CM_MODES=()=>[['normal',L('Обычное','Regular'),L('Остаётся в чате','Stays in the chat')],['once',L('Один просмотр','View once'),L('Открывается один раз, после закрытия исчезает','Opens once and is gone after closing')],['t15',L('15 минут после просмотра','15 minutes after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')],['t120',L('2 часа после просмотра','2 hours after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')],['t1440',L('24 часа после просмотра','24 hours after viewing'),L('Отсчёт начнётся, когда собеседник откроет','The countdown starts when they open it')]];
const chatNow=()=>Date.now()+(QA.clockShift||0);
/** one-time / timed media: unopened → open/counting → expired. Regular media never expires. */
function cmView(m,reader=pairMember()){if(!m.recipients?.length)return m;return(m.views??={})[reader]??={openedAt:null,done:false};}
function cmState(m,reader=pairMember()){if(m.mode==='normal')return'normal';const v=cmView(m,reader);if(v.done)return'expired';if(!v.openedAt)return'unopened';if(m.mode==='once')return'open';if(v.openedAt+CM_TTL[m.mode]<=chatNow()){v.done=true;if(!m.recipients||m.recipients.every(id=>m.views?.[id]?.done))m.url=null;return'expired';}return'counting';}
const cmLeft=m=>{const v=cmView(m),ms=Math.max(0,v.openedAt+CM_TTL[m.mode]-chatNow()),min=Math.ceil(ms/60e3);return min>=60?L(`${Math.ceil(min/60)} ч`,`${Math.ceil(min/60)} h`):L(`${min} мин`,`${min} min`);};
const cmModeLabel=m=>m.mode==='once'?L('один просмотр','view once'):m.mode==='normal'?'':L(`исчезнет через ${{t15:'15 мин',t120:'2 ч',t1440:'24 ч'}[m.mode]} после просмотра`,`gone ${{t15:'15 min',t120:'2 h',t1440:'24 h'}[m.mode]} after viewing`);
function chatMediaHTML(x,i){const m=x.media,states=x.me&&m.recipients?.length?m.recipients.map(reader=>cmState(m,reader)):null,st=m.mode==='normal'?'normal':states?(states.every(v=>v==='expired')?'expired':states.some(v=>v==='open')?'open':states.some(v=>v==='counting')?'counting':'unopened'):cmState(m),kind=m.type==='video'?L('Видео','Video'):L('Фото','Photo');
 if(st==='normal'){const hidden=!x.me&&S.me.chatBlur!==false&&!m.revealed;const thumb=m.type==='video'?`<video src="${esc(m.url)}" muted playsinline preload="metadata"></video>`:`<img src="${esc(m.url)}" alt="" draggable="false">`;
  return `<button class="mtile ${hidden?'blur':''}" data-act="chatMedia" data-v="${i}" aria-label="${hidden?L(`${kind} скрыто. Нажми, чтобы посмотреть`,`${kind} hidden. Tap to view`):L(`Открыть: ${kind}`,`Open ${kind}`)}">${thumb}${hidden?`<span class="mcover">${I.eyeoff}<b>${L('Нажми, чтобы посмотреть','Tap to view')}</b></span>`:''}</button>`;}
 const icon=m.mode==='once'?I.eye:I.timer;let line,sub='',can=false;
 if(x.me){line=`${kind} · ${cmModeLabel(m)}`;sub=st==='unopened'?L('ещё не просмотрено','not viewed yet'):st==='open'?L('открыто сейчас','open now'):st==='counting'?L(`просмотрено · осталось ${cmLeft(m)}`,`viewed · ${cmLeft(m)} left`):L('просмотр закончился, файла больше нет в чате','viewing ended; the file is gone from the chat');}
 else{can=st==='unopened'||st==='counting';line=`${kind} · ${cmModeLabel(m)}`;sub=st==='unopened'?(m.mode==='once'?L('нажми, чтобы открыть — посмотреть можно один раз','tap to open — you can view it once'):L('нажми, чтобы открыть — отсчёт начнётся с этого момента','tap to open — the countdown starts then')):st==='counting'?L(`можно открыть ещё · осталось ${cmLeft(m)}`,`can open again · ${cmLeft(m)} left`):st==='open'?L('открыто','open'):L('просмотр закончился','viewing ended');}
 return `<button class="mtile eph ${st}" ${can?`data-act="chatMedia" data-v="${i}"`:'disabled'}><span class="ico">${st==='expired'?I.check:icon}</span><span class="tx"><b>${line}</b><small>${sub}</small></span></button>`;}
ACT.chatMedia=a=>{const id=cur().p.id,t=chatStore().threads[id];const x=t?.msgs[+a.dataset.v];if(!x?.media||isBlocked(id))return;const m=x.media;const reader=pairMember();if(t.pair&&!x.me)m.recipients??=realMembers(t.actor);const v=cmView(m,reader),st=cmState(m,reader);
 if(st==='normal'){if(!x.me&&S.me.chatBlur!==false&&!m.revealed){m.revealed=true;refresh();return;}openViewer([{type:m.type,src:m.url}],0);return;}
 if(x.me||!authorAllowed(chatAuthor())||!isMatch(id)||!(st==='unopened'||st==='counting')||!m.url)return;
 if(!v.openedAt)v.openedAt=chatNow(); // the first conscious tap starts the timer, never a render
 openViewer([{type:m.type,src:m.url,wm:'@'+(S.me.nick||'')}],0,{label:m.mode==='once'?L('Один просмотр — после закрытия исчезнет','View once — gone after you close it'):L(`Осталось ${cmLeft(m)}`,`${cmLeft(m)} left`),onClose:()=>{if(m.mode==='once'){v.done=true;if(!m.recipients||m.recipients.every(id=>m.views?.[id]?.done))m.url=null;}if(cur()?.id==='H02')refresh();}});};
function chatSendSheet(){const c=S.ui.cm;if(!c)return{title:'',body:''};const kind=c.file.type==='video'?L('Видео','Video'):L('Фото','Photo');
 return{title:L(`Отправить: ${kind.toLowerCase()}`,`Send ${kind.toLowerCase()}`),body:`<div class="cm-prev">${c.file.type==='video'?`<video src="${esc(c.file.url)}" muted playsinline controls preload="metadata"></video>`:`<img src="${esc(c.file.url)}" alt="">`}</div>
 ${grp(L('Как можно смотреть','How it can be viewed'),choices(CM_MODES(),c.mode,'cmMode'))}
 <p class="note">${L('Скриншоты и запись экрана в браузере запретить нельзя. В приложении на телефоне мы попросим систему их скрыть, но полной гарантии нет.','Screenshots and screen recording can’t be blocked in a browser. In the phone app we ask the system to hide them, but there’s no full guarantee.')}</p>`,
 foot:`<button class="btn primary" data-act="cmSend">${I.send}${L('Отправить','Send')}</button>`};}
ACT.cmMode=a=>{S.ui.cm.mode=a.dataset.v;resheet();};
ACT.cmSend=a=>{const c=S.ui.cm;if(!c)return;const id=c.id,t=chatStore().threads[id];if(cur().p.id!==id||!isMatch(id)||isBlocked(id)||t.ended){S.ui.cm=null;closeSheet(true);return;}
 if(c.mode!=='normal'&&person(id).verified!==true){toast(L('Собеседник ещё не подтвердил возраст.','The recipient has not verified their age.'),{type:'warn'});return;}
 if(c.mode!=='normal'&&!needAge(()=>ACT.cmSend(a)))return;
 const owner=S,ticket=authorTicket(chatAuthor());const msg={me:1,author:chatAuthor(),sender:pairMember(),text:'',t:Date.now(),status:'sending',media:{type:c.file.type,url:c.file.url,mode:c.mode,recipients:t.pair?realMembers(id):undefined,views:{},openedAt:null,done:false}};S.ui.cm=null;closeSheet(true);t.msgs.push(msg);refresh();
 net(500).then(()=>{if(!validAuthor(ticket)||!isMatch(id,ticket.id)||t.ended)return;msg.status='';if(cur().id==='H02')refresh();
  // prototype: the other person opens a timed/once media a few seconds later, so the sender's states are visible
  if(!t.pair&&msg.media.mode!=='normal')setTimeout(()=>{if(S!==owner||msg.media.openedAt)return;msg.media.openedAt=chatNow();if(msg.media.mode==='once')setTimeout(()=>{msg.media.done=true;msg.media.url=null;if(cur()?.id==='H02')refresh();},4000);if(cur()?.id==='H02')refresh();},5000);
 }).catch(()=>{if(S!==owner)return;msg.status='failed';if(cur().id==='H02')refresh();toast(L('Не отправлено. Нажми «Повторить»','Not sent. Tap Retry'),{type:'err'});});};
/** countdown labels refresh while a timed media is counting; no timers otherwise */
function chatTick(){clearTimeout(S.ui.chatTickT);const r=cur();if(r?.id!=='H02')return;const t=chatStore().threads[r.p.id];if(!t?.msgs.some(x=>x.media&&['counting','open'].includes(cmState(x.media))))return;S.ui.chatTickT=setTimeout(()=>{if(cur()===r)refresh();},20000);}
/* H03/H04 — details, mute, archive, end connection, block */
ACT.chatMenu=a=>{const id=a.dataset.v;sheet(()=>({title:pname(id),lead:av(id,'sm round'),body:`<div class="card list">${linkRow({go:'P01',p:{id},icon:'me',title:L('Профиль','Profile')})}${linkRow({go:'P05',p:{id},icon:'spark',tone:'l',title:L('Что у вас общего','Shared interests')})}${givenGrant(id)?linkRow({act:'revoke',v:id,icon:'lock',tone:'v',title:L('Отозвать мой доступ','Revoke my access'),sub:L('Чат не изменится','The chat stays'),noChev:1}):''}</div>
 <div class="card list mt12">${toggleRow('chatMute',L('Без звука','Mute'),L('Сообщения приходят без уведомлений','Messages arrive silently'),chatStore().muted.has(id),`data-v="${id}"`)}${linkRow({act:'chatArchive',v:id,icon:'archive',title:chatStore().archived.has(id)?L('Вернуть из архива','Unarchive'):L('В архив','Archive'),sub:L('Не удаляет и не блокирует','Doesn’t delete or block'),noChev:1})}</div>
 <div class="card list mt12">${linkRow({act:'endConn',v:id,icon:'x',cls:'danger',title:L('Прекратить общение','End connection'),sub:L('Закрыть новые сообщения','Stop new messages'),noChev:1})}${linkRow({act:'report',v:'person',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}${linkRow({act:'block',v:id,icon:'block',cls:'danger',title:L('Заблокировать','Block'),noChev:1})}</div>`}));};
ACT.chatMute=a=>{const id=a.dataset.v;chatStore().muted.has(id)?chatStore().muted.delete(id):chatStore().muted.add(id);resheet();toast(chatStore().muted.has(id)?L('Без звука','Muted'):L('Звук включён','Unmuted'));};
ACT.chatArchive=a=>{const st=chatStore(),id=a.dataset.v;const was=st.archived.has(id);was?chatStore().archived.delete(id):chatStore().archived.add(id);closeSheet();if(!was&&cur().id==='H02')back();else refresh();toast(was?L('Диалог возвращён','Conversation restored'):L('Диалог в архиве. Новое сообщение вернёт его','Conversation archived. A new message brings it back'),{type:'ok',action:{label:L('Отменить','Undo'),fn:()=>{was?st.archived.add(id):st.archived.delete(id);refresh();}}});};
ACT.endConn=a=>{const id=a.dataset.v;S.ui.ec={revoke:true};closeSheet(true);sheet(()=>({title:L('Прекратить общение?','End this connection?'),lead:`<span class="ico l">${I.x}</span>`,body:`<p class="lead">${L(`${pname(id)} больше не сможет писать тебе, а ты — ей/ему. История останется у каждого по правилам хранения.`,`${pname(id)} won’t be able to message you, and you won’t message them. Each keeps the history under the retention rules.`)}</p>${givenGrant(id)?`<div class="card list">${toggleRow('ecRevoke',L('Также отозвать мои доступы','Also revoke my access'),L('Расширенный профиль закроется сразу','Your private profile closes immediately'),S.ui.ec.revoke)}</div>`:''}<p class="note mt12">${L('Это не блокировка: профиль и посты останутся видны. Для полной защиты используй «Заблокировать».','This isn’t blocking: profile and posts stay visible. For full protection use Block.')}</p>`,foot:`<button class="btn danger" data-act="ecDo" data-v="${id}">${L('Прекратить общение','End connection')}</button><button class="btn soft" data-act="closeSheet">${L('Отмена','Cancel')}</button>`}));};
ACT.ecRevoke=()=>{S.ui.ec.revoke=!S.ui.ec.revoke;resheet();};
ACT.ecDo=a=>{const id=a.dataset.v;run(a,()=>{chatStore().threads[id].ended=true;chatStore().matches=chatStore().matches.filter(m=>m.p!==id);if(S.ui.ec.revoke)chatStore().sharedByMe=chatStore().sharedByMe.filter(x=>x.p!==id);closeSheet();refresh();},{ok:L('Общение прекращено','Connection ended')});};
SC.H05={title:()=>L('Архив','Archive'),render:()=>{const owners=activePair()?['me','couple']:['me'];const rows=owners.flatMap(actor=>threadIds(true,actor).map(id=>chatRow(id,actor)));return `${bar(L('Архив','Archive'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${rows.join('')||empty('archive',L('Архив пуст','Archive is empty'))}</div></div>`;}};

/* N01 — one notification centre; counters derive from read state */
const NTXT={follow:n=>L(`<b>${pname(n.p)}</b> подписывается на тебя — твои публикации будут в ленте «Подписки»`,`<b>${pname(n.p)}</b> follows you — your posts will be in their Following feed`),match:n=>isMatch(n.p)?L(`<b>${pname(n.p)}</b> — это взаимно! Можно написать`,`<b>${pname(n.p)}</b> — it’s mutual! You can chat now`):L(`<b>${pname(n.p)}</b> — ранее было совпадение. Новый диалог сейчас недоступен`,`<b>${pname(n.p)}</b> — a previous match. You can’t start a new conversation now`),req:n=>L(`<b>${pname(n.p)}</b> просит открыть расширенный профиль`,`<b>${pname(n.p)}</b> asks to see your private profile`),event:n=>L(`Изменение: <b>${T(EV(n.e).title)}</b> — начало в 19:00`,`Change: <b>${T(EV(n.e).title)}</b> — starts at 19:00`),like:n=>L(`<b>${pname(n.p)}</b> отправил(а) тебе симпатию`,`<b>${pname(n.p)}</b> liked you`),reply:n=>n.parent?L(`<b>${esc(pname(n.p))}</b> ответил(а) в ветке`,`<b>${esc(pname(n.p))}</b> replied in your thread`):L(`<b>${esc(pname(n.p))}</b> ответил(а) на твою публикацию`,`<b>${esc(pname(n.p))}</b> replied to your post`),grant:n=>L(`<b>${pname(n.p)}</b> открыл(а) тебе расширенный профиль`,`<b>${pname(n.p)}</b> shared a private profile with you`),group:n=>L(`Новые правила в <b>${T(COMMUNITIES[n.c].name)}</b>`,`New rules in <b>${T(COMMUNITIES[n.c].name)}</b>`),evok:n=>L(`Событие <b>${T(EV(n.e).title)}</b> опубликовано`,`Your event <b>${T(EV(n.e).title)}</b> is live`),evapp:n=>L(`Заявка на <b>${T(EV(n.e).title)}</b> одобрена — адрес и детали открыты`,`Your application to <b>${T(EV(n.e).title)}</b> is approved — address and details are open`),groupok:n=>L(`Тебя приняли в <b>${T(COMMUNITIES[n.c].name)}</b>`,`You’re in <b>${T(COMMUNITIES[n.c].name)}</b>`),postok:()=>L('Публикация с фото прошла проверку и видна в ленте','Your post with photos passed review and is in the feed')};
NTXT.pair=n=>`<b>${esc(n.pairName||L('Совместный профиль','Couple profile'))}</b> · ${esc(({proposal:L('Версия профиля на согласовании','Profile revision awaiting approval'),profileApproved:L('Профиль согласован','Profile approved'),returned:L('Версия возвращена на доработку','Revision returned for changes'),dissolved:L('Совместный профиль отключён','Couple profile deactivated'),restored:L('Связь восстановлена','Connection restored'),restoreRequested:L('Запрос восстановления связи','Connection recovery requested'),reply:L('Новый ответ на публикацию пары','New reply to a couple post'),match:L('Новая взаимная симпатия пары','New mutual couple like'),message:L('Новое сообщение в совместном чате','New message in couple chat'),like:L('Новая симпатия пары','New couple like'),req:L('Запрос к расширенному профилю пары','Request for couple private profile'),grant:L('Доступ пары изменён','Couple access changed')})[n.pairEvent]||L('Новое уведомление','New notification'))}`;
const NICO={evapp:['check','g'],groupok:['users3','g'],postok:['check','g'],follow:['users3','v'],match:['heart','l'],req:['lock','v'],event:['cal','a'],like:['heart','l'],reply:['chat','g'],grant:['unlock','g'],group:['users3','v'],evok:['check','g']};
SC.N01={title:()=>L('Уведомления','Notifications'),render:(p)=>{const k=p.k||'all';const acts=['match','req','like','grant','reply','follow'];
 const list=currentNotifications().filter(n=>!(n.p&&isBlocked(n.p))&&(k==='all'||(k==='act'?acts.includes(n.type):!acts.includes(n.type))));
 const neu=list.filter(n=>!n.read),old=list.filter(n=>n.read);
 const row=n=>{const [i,t]=NICO[n.type]||['bell',''];return `<button class="nt ${n.read?'':'unread'}" data-act="openNotif" data-v="${n.id}"><span class="ntw">${n.p?av(n.p,''):`<span class="av" style="position:relative">${plate(n.e?EV(n.e).plate:n.c?COMMUNITIES[n.c].plate:'rose')}</span>`}<span class="ico ${t}">${I[i]}</span></span><span class="tx">${NTXT[n.type](n)}<time>${F.rel(n.t)}</time></span>${n.read?'':'<span class="dotu" aria-label="new"></span>'}</button>`;};
 return `${bar(L('Уведомления','Notifications'),{back:1,sm:1,actions:C.notif()?`<button class="btn text auto" data-act="readAll">${L('Прочитать все','Mark all read')}</button>`:`<button class="ibtn ghost" data-go="K05" aria-label="${L('Настройки уведомлений','Notification settings')}">${I.gear}</button>`})}<div class="view nodock"><div class="wrap">
 ${seg([['all',L('Все','All')],['act',L('Люди','People')],['upd',L('События и группы','Events & groups')]],k,'nTab','sm')}
 ${list.length?`${neu.length?`<div class="sec" style="margin-top:4px">${L('Новые','New')}</div>${neu.map(row).join('')}`:''}${old.length?`<div class="sec">${L('Ранее','Earlier')}</div>${old.map(row).join('')}`:''}`:empty('bell',L('Уведомлений нет','No notifications'),L('Здесь появятся симпатии, совпадения, запросы и изменения событий.','Likes, matches, requests and event changes appear here.'))}
 <p class="note mt16">${((S.me.notif?.mode||'safe')==='safe'?L('На экране блокировки — нейтрально: «Новое уведомление», без имён и текста. Меняется в настройках.','On the lock screen — discreet: “New notification”, no names or text. Change it in settings.'):L('На экране блокировки видны имя и начало сообщения. Меняется в настройках.','The lock screen shows the name and message preview. Change it in settings.'))}</p></div></div>`;}};
ACT.nTab=a=>setP('k',a.dataset.v);
ACT.readAll=()=>{currentNotifications().forEach(n=>{n.read=true;const u=S.updates.find(x=>x.id===n.id);if(u)u.read=true;});refresh();toast(L('Все прочитаны','All marked as read'),{type:'ok'});};
ACT.openNotif=a=>{const n=currentNotifications().find(x=>x.id===a.dataset.v);if(!n||(n.p&&isBlocked(n.p)))return;n.read=true;const update=S.updates.find(x=>x.id===n.id);if(update)update.read=true;if(n.type==='match'&&n.p){if(isMatch(n.p))return openChat(n.p);return tab('chats',{sub:'chats'});}const [id,p]=n.go||['Q03',{}];if(id==='H01')return tab('chats',p||{sub:'chats'});go(id,p||{});};
/* N02 — ask for push only after a useful action */
function maybePush(){if(S.ui.pushAsked)return;S.ui.pushAsked=1;setTimeout(()=>sheet(()=>({title:L('Не пропустить ответ?','Don’t miss a reply?'),lead:`<span class="ico l">${I.bell}</span>`,body:`<p class="lead">${L('Пришлём уведомление, когда ответят или придёт взаимная симпатия. Текст нейтральный — без имён и подробностей.','We’ll notify you about replies and mutual likes. The text is neutral — no names or details.')}</p><div class="card flat row" style="gap:10px"><img src="${LOGO()}" alt="" style="width:34px"><div class="grow"><b style="font-size:14px">FetUre</b><div class="note">${L('У тебя новое уведомление','You have a new notification')}</div></div></div>`,foot:`<button class="btn primary" data-act="pushOk">${L('Включить уведомления','Turn on notifications')}</button><button class="btn text" data-act="closeSheet">${L('Позже','Later')}</button>`})),900);}
ACT.pushOk=()=>{closeSheet();toast(L('Уведомления включены','Notifications on'),{type:'ok'});};

